/* Deterministic, goal-specific guidance from individually admitted canonical claims. */
(function(){
 'use strict';
 const a=window.VersionCompassAIAvailability,esc=a.esc;
 const goals={unknown:'Choose a goal','agent-mode':'Explore SAIA Agent Mode','itsi-versions':'Check ITSI assistant version prerequisites','itsi-assistant':'Explore ITSI assistance','soc-workflow':'Explore the ES AI SOC workflow','ingest-pressure':'Address reported ingest pressure',stay:'Keep my current capabilities'};
 const choices={deployment:{unknown:'Unknown',enterprise:'Splunk Enterprise',cloud:'Splunk Cloud'},compliance:{unknown:'Unknown',commercial:'Commercial','fr-m':'FedRAMP Moderate','fr-h':'FedRAMP High'},edition:{unknown:'Unknown',essentials:'ES Essentials',premier:'ES Premier'},access:{unknown:'Unknown',yes:'Reported confirmed',no:'Reported not confirmed'}};
 const defaults={goal:'unknown',deployment:'unknown',compliance:'unknown',region:'unknown',edition:'unknown',access:'unknown',platformVersion:'',itsiVersion:'',saiaVersion:'',mcpVersion:''};
 function normalize(input={}){const state={...defaults};for(const key of Object.keys(state)){const v=input[key];if(typeof v==='string')state[key]=v.slice(0,40);}
  if(!goals[state.goal])state.goal='unknown';for(const key of Object.keys(choices))if(!choices[key][state[key]])state[key]='unknown';
  if(state.region!=='unknown'&&!a.regions().some(r=>r.id===state.region))state.region='unknown';return state;}
 function read(search){const p=new URLSearchParams(search),errors=[];for(const key of new Set(p.keys())){if(!['view','goal','theme'].includes(key))errors.push('The field '+key+' is not part of an Advisor link. Profiles stay on this device.');if(p.getAll(key).length!==1)errors.push('The field '+key+' appears more than once.');}
  if(p.get('view')!=='advisor')errors.push('This link does not identify Advisor.');if(p.has('goal')&&!goals[p.get('goal')])errors.push('This goal is not recognized.');if(p.has('theme')&&p.get('theme')!=='cisco')errors.push('This theme is not recognized.');return {state:normalize({goal:p.get('goal')||'unknown'}),errors};}
 function resolve(ref){const [kind,key]=ref.split(':');return kind==='capability'?a.data().capabilities.find(r=>r.id===key):kind==='source'?a.source(key):kind==='policy'?a.data()[key]:kind==='environment'?window.VersionCompassEnvironmentData[key]:undefined;}
 function admission(goal){const registry=window.VersionCompassAdvisorAdmission,ids=registry?.goals[goal]||[];const claims=ids.map(id=>registry.claims.find(c=>c.id===id));const rejected=claims.filter(c=>!c||!window.VersionCompassHash||resolve(c.ref)===undefined||window.VersionCompassHash(JSON.stringify(resolve(c.ref)))!==c.sha256);
  return {ok:ids.length>0&&!rejected.length,claims:rejected.length?[]:claims,rejected:rejected.map(c=>c?.id||'Missing admission')};}
 function version(value){if(!/^\d{1,3}\.\d{1,3}(?:\.\d{1,3}){0,2}$/.test(value))return null;return value.split('.').map(Number);}
 function floor(value,minimum){const v=version(value),m=minimum.split('.').map(Number);if(!v)return 'unknown';for(let i=0;i<Math.max(v.length,m.length);i++){const x=v[i]||0,y=m[i]||0;if(x!==y)return x>y?'meets':'below';}return 'meets';}
 function evaluate(input){const s=normalize(input),result={state:s,status:'insufficient',title:'More evidence is needed',summary:'Choose a specific goal to see the assessed documentation that can support it.',gaps:[],checks:[],conflicts:[],sources:[],record:null,authorization:'not_established'};
  if(s.goal==='stay')return {...result,status:'no_change',title:'No change proposed',summary:'You chose to keep your current capabilities. Advisor has no goal-specific reason to propose a version change. This does not assess support, security, health or entitlement.'};
  if(s.goal==='ingest-pressure')return {...result,summary:'Reported ingest pressure alone does not establish its cause or a supported remedy. This build has insufficient assessed evidence for licensing, sizing or operational recommendations.',gaps:['No capacity, licensing or operational change is proposed. Those areas remain future scope, subject to assessed evidence.']};
  if(s.goal==='unknown')return result;
  const admitted=admission(s.goal);if(!admitted.ok)return {...result,title:'Evidence needs reassessment',summary:'A supporting claim or source has changed since admission. This goal is paused until its exact scope is reviewed.',gaps:admitted.rejected};
  const id=s.goal==='agent-mode'?'ai-saia-agent':s.goal==='soc-workflow'?'ai-es-soc':'ai-itsi-subagent',record=resolve('capability:'+id);result.record=record;result.admitted=admitted.claims.map(c=>({id:c.id,scope:c.scope,ref:c.ref}));
  result.sources=[...new Set(admitted.claims.flatMap(c=>c.sources||[]))].map(id=>({id,...a.source(id)}));
  if(s.goal==='soc-workflow'){
   result.status='conflicting';result.title='Conflicting scope needs clarification';result.conflicts=[{text:'The ES 8.8 aggregate workflow row requires Premier and lists Cloud ES 8.6+, while the ES 8.7 task guide requires ES 8.7+. The 8.8 Triage component note assigns Essentials, while the editions overview groups Triage under Premier.',impact:'Do not treat a component as access to the whole workflow or choose an upgrade target from the lower aggregate floor. Confirm the exact task, edition and version with Splunk before proceeding.',sources:['aiEsAgents88','aiEsSocTask87','aiEsEditions']}];result.gaps.push('Paired SOAR compatibility, representative enablement, model support and task permissions need independent confirmation.');
  }
  const check=(label,field,minimum)=>{const outcome=floor(s[field],minimum);result.checks.push({label,reported:s[field]||'Unknown',minimum,outcome});if(outcome==='unknown')result.gaps.push('Confirm the installed '+label+' version.');if(outcome==='below')result.gaps.push(label+' is below the documented '+minimum+'+ prerequisite. Review a supported upgrade path before changing it.');};
  if(s.goal==='itsi-versions'||s.goal==='itsi-assistant'){check('ITSI','itsiVersion','5.0.0');check('SAIA','saiaVersion','2.2.0');check('Splunk MCP Server','mcpVersion','1.2.1');}
  if(s.goal==='itsi-versions'){
   const outcomes=result.checks.map(c=>c.outcome);result.status=outcomes.includes('unknown')?'insufficient':outcomes.includes('below')?'prerequisite':'no_change';result.title=result.status==='no_change'?'No version change indicated for these floors':result.status==='prerequisite'?'Documented prerequisite gaps':'Confirm the installed versions';
   result.summary='This compares only the three version floors in the assessed ITSI integration claim. '+(result.status==='no_change'?'Your reported versions meet those floors. ':'')+'It does not establish a supported complete pairing, regional rollout, permissions, access or authorization.';return result;
  }
  if(s.deployment==='unknown')result.gaps.push('Confirm the deployment.');if(s.compliance==='unknown')result.gaps.push('Confirm the service environment.');if(s.region==='unknown')result.gaps.push('Confirm the exact AI service region.');if(s.access!=='yes')result.gaps.push('Access and enablement are not reported confirmed. No license or entitlement is inferred.');
  if(s.goal==='agent-mode'&&s.deployment==='enterprise')check('Platform','platformVersion','10.1.0');
  if(s.compliance!=='commercial'){result.summary='This build cannot establish this capability for the selected regulated or unknown environment from its admitted documentation. It does not infer customer authorization.';result.gaps.push('Regulated rollout, mode and runtime evidence remain unresolved for this goal.');return result;}
  if(s.deployment==='unknown'){result.summary='A deployment-specific path needs a confirmed deployment context.';return result;}
  const availability=a.assess(record,{deployment:s.deployment,compliance:s.compliance,region:s.region==='unknown'?'all':s.region,csp:'all',edition:s.edition==='unknown'?'all':s.edition});result.availability=availability.availability;result.summary=availability.detail;
  if(s.goal==='soc-workflow')return result;
  if(s.goal==='itsi-assistant'){result.summary='The integration and version floors are documented. Subagent-specific regional rollout is not independently established; a listed base-assistant region cannot establish it.';result.gaps.push('Obtain documentation for the ITSI subagent’s exact regional rollout.');return result;}
  if(['not_established','conflicting','unavailable'].includes(availability.availability)){result.title=availability.availability==='unavailable'?'A documented limitation applies':'Availability is not established';return result;}
  if(result.gaps.length){result.title=result.checks.some(c=>c.outcome==='below')?'Documented prerequisites need attention':'Confirm the remaining prerequisites';result.status=result.checks.some(c=>c.outcome==='below')?'prerequisite':'insufficient';return result;}
  result.status='conditional';result.title='A documented path to investigate';result.summary+=' This is a conditional documentation path, based on your reports. Confirm the supported app/Platform pairing, permissions, activation and model/runtime policy; Advisor has not validated them.';return result;
 }
 function sources(result){return '<ol class="ai-sources">'+result.sources.map(s=>'<li><strong>'+esc(s.title)+'</strong><br><a href="'+esc(s.url)+'">'+esc(s.url)+'</a><p>Supporting section: '+esc(s.section)+' · Source checked '+esc(s.checked)+' · Scope reviewed '+esc(s.reviewed)+' · '+esc(s.scope)+'</p></li>').join('')+'</ol>';}
 function resultHTML(result){return '<article class="advisor-result" data-outcome="'+result.status+'"><p class="kicker">'+esc(result.status.replace('_',' '))+'</p><h2>'+esc(result.title)+'</h2><p>'+esc(result.summary)+'</p>'+(result.gaps.length?'<h3>What still needs confirmation</h3><ul>'+result.gaps.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'')+(result.checks.length?'<h3>Documented version prerequisites</h3><ul>'+result.checks.map(c=>'<li><strong>'+esc(c.label)+'</strong>: reported '+esc(c.reported)+'; documented floor '+esc(c.minimum)+'+ — '+esc(c.outcome)+'</li>').join('')+'</ul>':'')+result.conflicts.map(c=>'<aside class="advisor-conflict"><h3>Unresolved source contradiction</h3><p>'+esc(c.text)+'</p><p><strong>Impact:</strong> '+esc(c.impact)+'</p><p>'+c.sources.map(id=>'<a href="'+esc(a.source(id).url)+'">'+esc(a.source(id).title)+'</a>').join(' · ')+'</p></aside>').join('')+(result.record?'<details open><summary>Assessed claim and its limits</summary><h3>'+esc(result.record.title)+'</h3><p>'+esc(result.record.version)+' · '+esc(result.record.stage)+'</p><ul>'+result.record.requirements.map(r=>'<li>'+esc(r)+'</li>').join('')+'</ul><p>'+esc(result.record.qualification)+'</p><p>Claim verified '+esc(result.record.verified)+'. Authorization: not established.</p></details><p><a href="/?view=ai-availability">Explore the complete AI evidence</a> · <a href="/">Review the Release Guide</a></p>':'')+'</article>';}
 function report(state){const result=evaluate(state),html='<article><header class="report-title"><p>VERSION COMPASS / ADVISOR · WORK IN PROGRESS</p><h1>Advisor</h1><p>'+esc(goals[state.goal])+'</p></header><section class="report-section"><h2>Self-reported context</h2><p>Unverified inputs. This report does not establish entitlement, health, compliance or authorization. Profiles remain local; a shared link contains the goal only.</p><ul>'+Object.entries(state).map(([k,v])=>'<li>'+esc(k)+': '+esc(v||'Unknown')+'</li>').join('')+'</ul></section><section class="report-section">'+resultHTML(result)+'</section><section class="report-section"><h2>Sources and claim admission</h2>'+sources(result)+'<p>Only individually admitted claims from assessed published Splunk documentation support this result. Source and claim dates retain their original scope. A changed pinned claim pauses its goal.</p></section><section class="report-section"><h2>Current scope</h2><p>Deterministic guidance; no runtime model. Licensing, sizing and operational advice without sufficient assessed evidence are excluded and remain future potential.</p></section></article>';return '<div class="edition-report advisor-report">'+(window.VersionCompassReports?.decorate(html)||html)+'</div>';}
 window.VersionCompassAdvisor={goals,choices,defaults,normalize,read,resolve,admission,version,floor,evaluate,esc,resultHTML,sources,report};
}());
